<?php

namespace Tests\Support;

use Illuminate\Support\Facades\DB;
use LogicException;
use PDO;

/** P8 journals extend the same owned P5 ledger and reference its sealed source journals. */
final class LifecycleStoreFixture
{
    public static function install(PDO $pdo): void
    {
        $databases = $pdo->query('PRAGMA database_list')->fetchAll(PDO::FETCH_ASSOC);
        if (PHP_SAPI !== 'cli' || getenv('XLIPA_SYNTHETIC_ONLY') !== '1' || ! app()->environment('testing') || count($databases) !== 1 || $databases[0]['file'] !== '' || $pdo === DB::connection()->getPdo() || (int) $pdo->query("SELECT count(*) FROM sqlite_master WHERE name='ledger_seals'")->fetchColumn() !== 1) {
            throw new LogicException('Lifecycle requires the distinct owned P5 memory ledger.');
        }
        $pdo->exec("CREATE TABLE funds_withdrawals(reference TEXT PRIMARY KEY NOT NULL,merchant_id TEXT NOT NULL,actor_id INTEGER NOT NULL,request_key TEXT NOT NULL,destination_reference TEXT NOT NULL,destination_mask TEXT NOT NULL,amount_tzs INTEGER NOT NULL CHECK(typeof(amount_tzs)='integer' AND amount_tzs BETWEEN 1 AND 1000000000000),created_at INTEGER NOT NULL,UNIQUE(merchant_id,request_key),FOREIGN KEY(reference) REFERENCES ledger_lifecycle_journals(withdrawal_reference) DEFERRABLE INITIALLY DEFERRED)");
        $pdo->exec("CREATE TABLE ledger_lifecycle_journals(id TEXT PRIMARY KEY NOT NULL,merchant_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('settlement','reserve','release','payout')),amount_tzs INTEGER NOT NULL CHECK(typeof(amount_tzs)='integer' AND amount_tzs BETWEEN 1 AND 1000000000000),source_journal TEXT REFERENCES ledger_seals(journal_id),withdrawal_reference TEXT UNIQUE REFERENCES funds_withdrawals(reference),related_withdrawal TEXT REFERENCES funds_withdrawals(reference),evidence_hash TEXT NOT NULL,event_id TEXT NOT NULL UNIQUE,body TEXT NOT NULL,signature TEXT NOT NULL,posted_at INTEGER NOT NULL,FOREIGN KEY(id) REFERENCES ledger_lifecycle_seals(journal_id) DEFERRABLE INITIALLY DEFERRED,CHECK((kind='settlement' AND source_journal IS NOT NULL AND withdrawal_reference IS NULL AND related_withdrawal IS NULL) OR (kind='reserve' AND source_journal IS NULL AND withdrawal_reference IS NOT NULL AND related_withdrawal IS NULL) OR (kind IN ('release','payout') AND source_journal IS NULL AND withdrawal_reference IS NULL AND related_withdrawal IS NOT NULL)),UNIQUE(source_journal),UNIQUE(related_withdrawal))");
        $pdo->exec("CREATE TABLE ledger_lifecycle_postings(journal_id TEXT NOT NULL REFERENCES ledger_lifecycle_journals(id),line INTEGER NOT NULL,account TEXT NOT NULL CHECK(account IN ('simulated_settled_cash','simulated_clearing_receivable','merchant_pending_obligation','merchant_available_obligation','merchant_reserved_obligation')),direction TEXT NOT NULL CHECK(direction IN ('debit','credit')),amount_tzs INTEGER NOT NULL CHECK(typeof(amount_tzs)='integer' AND amount_tzs>0),PRIMARY KEY(journal_id,line))");
        $pdo->exec('CREATE TABLE ledger_lifecycle_seals(journal_id TEXT PRIMARY KEY NOT NULL REFERENCES ledger_lifecycle_journals(id))');
        $pdo->exec('CREATE TABLE funds_dispatches(withdrawal_reference TEXT PRIMARY KEY NOT NULL REFERENCES funds_withdrawals(reference),attempted_at INTEGER NOT NULL)');
        $pdo->exec("CREATE TABLE funds_events(event_id TEXT PRIMARY KEY NOT NULL,withdrawal_reference TEXT NOT NULL REFERENCES funds_withdrawals(reference),merchant_id TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('pending','confirmed','failed','unresolved')),body TEXT NOT NULL,signature TEXT NOT NULL,body_hash TEXT NOT NULL,received_at INTEGER NOT NULL)");
        $pdo->exec('CREATE INDEX funds_events_withdrawal ON funds_events(withdrawal_reference,received_at,event_id)');
        $pdo->exec('CREATE INDEX lifecycle_merchant ON ledger_lifecycle_journals(merchant_id,kind)');
        $pdo->exec("CREATE UNIQUE INDEX lifecycle_settlement_transaction ON ledger_lifecycle_journals(json_extract(body,'$.provider_transaction')) WHERE kind='settlement'");
        $pdo->exec("CREATE TRIGGER lifecycle_no_overdraw BEFORE INSERT ON ledger_lifecycle_journals WHEN NEW.kind='reserve' AND NEW.amount_tzs>(SELECT coalesce(sum(CASE WHEN kind IN ('settlement','release') THEN amount_tzs WHEN kind='reserve' THEN -amount_tzs ELSE 0 END),0) FROM ledger_lifecycle_journals WHERE merchant_id=NEW.merchant_id) BEGIN SELECT RAISE(ABORT,'Insufficient simulated funds'); END");
        $pdo->exec("CREATE TRIGGER lifecycle_source BEFORE INSERT ON ledger_lifecycle_journals WHEN (NEW.kind='settlement' AND NOT EXISTS(SELECT 1 FROM ledger_journals j JOIN ledger_seals s ON s.journal_id=j.id WHERE j.id=NEW.source_journal AND j.merchant_id=NEW.merchant_id AND j.amount_tzs=NEW.amount_tzs AND j.posted_at<=NEW.posted_at)) OR (NEW.kind<>'settlement' AND NOT EXISTS(SELECT 1 FROM funds_withdrawals w WHERE w.reference=coalesce(NEW.withdrawal_reference,NEW.related_withdrawal) AND w.merchant_id=NEW.merchant_id AND w.amount_tzs=NEW.amount_tzs AND w.created_at<=NEW.posted_at)) BEGIN SELECT RAISE(ABORT,'Lifecycle source mismatch'); END");
        $pdo->exec("CREATE TRIGGER lifecycle_posting_shape BEFORE INSERT ON ledger_lifecycle_postings WHEN NOT EXISTS(SELECT 1 FROM ledger_lifecycle_journals j WHERE j.id=NEW.journal_id AND j.amount_tzs=NEW.amount_tzs AND ((j.kind='settlement' AND ((NEW.line=1 AND NEW.account='simulated_settled_cash' AND NEW.direction='debit') OR (NEW.line=2 AND NEW.account='simulated_clearing_receivable' AND NEW.direction='credit') OR (NEW.line=3 AND NEW.account='merchant_pending_obligation' AND NEW.direction='debit') OR (NEW.line=4 AND NEW.account='merchant_available_obligation' AND NEW.direction='credit'))) OR (j.kind='reserve' AND ((NEW.line=1 AND NEW.account='merchant_available_obligation' AND NEW.direction='debit') OR (NEW.line=2 AND NEW.account='merchant_reserved_obligation' AND NEW.direction='credit'))) OR (j.kind='release' AND ((NEW.line=1 AND NEW.account='merchant_reserved_obligation' AND NEW.direction='debit') OR (NEW.line=2 AND NEW.account='merchant_available_obligation' AND NEW.direction='credit'))) OR (j.kind='payout' AND ((NEW.line=1 AND NEW.account='merchant_reserved_obligation' AND NEW.direction='debit') OR (NEW.line=2 AND NEW.account='simulated_settled_cash' AND NEW.direction='credit'))))) BEGIN SELECT RAISE(ABORT,'Lifecycle posting mismatch'); END");
        $pdo->exec("CREATE TRIGGER lifecycle_posting_open BEFORE INSERT ON ledger_lifecycle_postings WHEN EXISTS(SELECT 1 FROM ledger_lifecycle_seals WHERE journal_id=NEW.journal_id) BEGIN SELECT RAISE(ABORT,'Journal sealed'); END");
        $pdo->exec("CREATE TRIGGER lifecycle_balanced BEFORE INSERT ON ledger_lifecycle_seals WHEN NOT EXISTS(SELECT 1 FROM ledger_lifecycle_journals j WHERE j.id=NEW.journal_id AND (SELECT count(*) FROM ledger_lifecycle_postings WHERE journal_id=j.id)=CASE WHEN j.kind='settlement' THEN 4 ELSE 2 END AND (SELECT sum(amount_tzs) FROM ledger_lifecycle_postings WHERE journal_id=j.id AND direction='debit')=j.amount_tzs*CASE WHEN j.kind='settlement' THEN 2 ELSE 1 END AND (SELECT sum(amount_tzs) FROM ledger_lifecycle_postings WHERE journal_id=j.id AND direction='credit')=j.amount_tzs*CASE WHEN j.kind='settlement' THEN 2 ELSE 1 END) BEGIN SELECT RAISE(ABORT,'Balanced lifecycle journal required'); END");
        foreach (['funds_withdrawals', 'ledger_lifecycle_journals', 'ledger_lifecycle_postings', 'ledger_lifecycle_seals', 'funds_dispatches', 'funds_events'] as $table) {
            foreach (['UPDATE', 'DELETE'] as $operation) {
                $pdo->exec("CREATE TRIGGER {$table}_".strtolower($operation)." BEFORE $operation ON $table BEGIN SELECT RAISE(ABORT,'Funds history immutable'); END");
            }
            $identity = match ($table) {
                'funds_withdrawals' => 'reference=NEW.reference OR (merchant_id=NEW.merchant_id AND request_key=NEW.request_key)','ledger_lifecycle_journals' => 'id=NEW.id OR event_id=NEW.event_id OR (source_journal IS NOT NULL AND source_journal=NEW.source_journal) OR (related_withdrawal IS NOT NULL AND related_withdrawal=NEW.related_withdrawal)','ledger_lifecycle_postings' => 'journal_id=NEW.journal_id AND line=NEW.line','ledger_lifecycle_seals' => 'journal_id=NEW.journal_id','funds_dispatches' => 'withdrawal_reference=NEW.withdrawal_reference','funds_events' => 'event_id=NEW.event_id'
            };
            $pdo->exec("CREATE TRIGGER {$table}_replace BEFORE INSERT ON $table WHEN EXISTS(SELECT 1 FROM $table WHERE $identity) BEGIN SELECT RAISE(ABORT,'Funds replacement denied'); END");
        }
    }
}
